"Favourite every checked take (all favourites already: taken back)": "Mettre chaque prise cochée en favori (toutes déjà favorites : retiré)",
"Add to workspace": "Ajouter à l'espace",
"Into that workspace and out of this one (out of every other when you are in All Workspaces)": "Dans cet espace et hors de celui-ci (hors de tous les autres quand tu es dans Tous les espaces)",
"Move to workspace": "Déplacer vers l'espace",
"Take out of this workspace": "Retirer de cet espace",
"Out of the lists, not deleted: Hidden on the left shows them again": "Hors des listes, pas supprimées : Masquées à gauche les montre à nouveau",
"Hide": "Masquer",
"Export format": "Format d'export",
"FLAC: lossless, about half the size of WAV. WAV: for tools that take nothing else.": "FLAC : sans perte, environ la moitié de la taille du WAV. WAV : pour les outils qui ne prennent rien d'autre.",
"Also every file made from each take (remasters, stems, upscales, debuzzed files), named after the take.": "Aussi chaque fichier fait à partir de chaque prise (remasterings, stems, suréchantillonnages, fichiers débourdonnés), nommé d'après la prise.",
"with what is made from them": "avec ce qui en est fait",
"A ZIP made on Forge, then saved by the browser where you tell it": "Un ZIP fait sur Forge, puis enregistré par le navigateur là où tu le lui dis",
"Export ZIP": "Exporter en ZIP",
"To the trash": "À la corbeille",
"The Librarian lives in Forge's lab, which does not answer: not found": "Le Bibliothécaire vit dans le labo de Forge, qui ne répond pas : introuvable",
"a LoRA for YuE2 from your own songs · the guide: LORA-TRAINING.md": "une LoRA pour YuE2 à partir de tes propres chansons · le guide : LORA-TRAINING.md",
