"Search runs · set · kind": "Chercher les exécutions · ensemble · type",
"The server log, in every room: click to unfold or fold": "Le journal du serveur, dans chaque salle : clique pour déplier ou replier",
"The line to the studio: the round trip, the middle of the last five (every 20 s). Near: the studio answers at once.": "La ligne vers le studio : l'aller-retour, la médiane des cinq derniers (toutes les 20 s). Près : le studio répond aussitôt.",
"Follow: the log keeps to its newest line as the engine writes. Off: it stays where you scrolled to read.": "Suivre : le journal reste sur sa ligne la plus récente pendant que le moteur écrit. Désactivé : il reste là où tu as défilé pour lire.",
"The whole log, in Engine": "Tout le journal, dans Moteur",
"Unfold the takes list": "Déplier la liste des prises",
