"Every workspace's takes in this column, whatever workspace is in hand (new takes still land in that one); the column's other filters still apply": "Les prises de tous les espaces dans cette colonne, quel que soit l'espace en main (les nouvelles prises vont toujours dans celui-là) ; les autres filtres de la colonne s'appliquent",
