"≈ A guess: the painter does not know this instrument, and the critic did not find it in any of the pictures it drew.": "≈ Une supposition : le peintre ne connaît pas cet instrument, et le critique ne l'a trouvé dans aucune des images qu'il a dessinées.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten. Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "⚠ Un nom dans le style est une demande, pas une promesse. Ce que jouent ▶ A et ▶ B, c'est ce que YuE2 donne pour lui, environ neuf fois sur dix. Certains essais sont superbes, A et B s'accordent, et pourtant l'instrument n'est pas celui demandé : fie-toi à l'oreille, pas au nom.",
