"Each song renders {#0} times with sound seeds seed, seed + 1…; the music is written once.": {"one": "Chaque chanson est rendue {#0} fois avec les graines sonores graine, graine + 1… ; la musique n'est écrite qu'une fois.", "other": "Chaque chanson est rendue {#0} fois avec les graines sonores graine, graine + 1… ; la musique n'est écrite qu'une fois."},
