"(the mix, every stem, the score as notes, the sections as markers: Waveform 14, Bitwig, Studio One, Cubase); both also in a take’s menu → Download. Waveform: 14 or newer.": "(le mix, chaque stem, la partition en notes, les sections en marqueurs : Waveform 14, Bitwig, Studio One, Cubase) ; les deux aussi dans le menu d'une prise → Télécharger. Waveform : 14 ou plus récent.",
"Packing…": "Emballage…",
"60 days of evaluation with every function, then a licence: $60 for personal use or a small business": "60 jours d'évaluation avec toutes les fonctions, puis une licence : 60 $ pour un usage personnel ou une petite entreprise",
"Waveform Free 14 or newer: free, no track or export limits; it opens the studio's DAWproject (File > Import Other > Import a DAWproject file). Waveform 13 is not supported": "Waveform Free 14 ou plus récent : gratuit, sans limite de pistes ni d'export ; il ouvre le DAWproject du studio (File > Import Other > Import a DAWproject file). Waveform 13 n'est pas pris en charge",
"30 days without limits after signing up, then Essentials $99, Producer $199 or Studio $399 (bitwig.com, 03.10.2026); opens the studio's DAWproject: the mix, the stems, the score as notes, the sections as markers": "30 jours sans limites après inscription, puis Essentials 99 $, Producer 199 $ ou Studio 399 $ (bitwig.com, 03.10.2026) ; ouvre le DAWproject du studio : le mix, les stems, la partition en notes, les sections en marqueurs",
"reaper.fm/download.php → the Linux x86_64 tarball → unpack it and run ./install-reaper.sh (it goes to /opt/REAPER)": "reaper.fm/download.php → l'archive Linux x86_64 → décompresse-la et lance ./install-reaper.sh (il s'installe dans /opt/REAPER)",
