"bitwig.com/download: the Ubuntu .deb (sudo apt install ./bitwig-studio-*.deb) or the Flatpak": "bitwig.com/download : le .deb pour Ubuntu (sudo apt install ./bitwig-studio-*.deb) ou le Flatpak",
