"The current official decoder, and the default. The cleanest, best-sounding one: start here.": "Le décodeur officiel actuel, et celui par défaut. Le plus propre, le meilleur son : commence par lui.",
"The older official decoder. The published benchmark scores were made with it. Less clean than Standard; some hear it as more musical. Same encoder, only the decoder differs.": "L'ancien décodeur officiel. Les scores de benchmark publiés ont été faits avec lui. Moins propre que Standard ; certains l'entendent plus musical. Même encodeur, seul le décodeur diffère.",
"A community weight mix of the two official decoders: 2/3 Standard + 1/3 Legacy. Not newly trained. It sits between the clean Standard and the more musical Legacy; the real-audio LoRA's authors suggest it.": "Un mélange communautaire des poids des deux décodeurs officiels : 2/3 Standard + 1/3 Legacy. Pas réentraîné. Il se place entre le Standard propre et le Legacy plus musical ; les auteurs du LoRA d'audio réel le suggèrent.",
