"The studio's approved sets, as their author published them. Each comes in as a workspace of its own, locked against deletion: its takes as MP3 with their covers, titles and notes. Only what you ask for is downloaded.": "Les ensembles approuvés du studio, tels que leur auteur les a publiés. Chacun arrive comme un espace à lui, verrouillé contre la suppression : ses prises en MP3 avec leurs pochettes, titres et notes. Seul ce que tu demandes est téléchargé.",
