"Drag a point up for a flare, down for a fade, along the song to move it; double-click to add one, double-click a point to take it out. The strength above is the top of the curve.": "Monte un point pour un élan, descends-le pour un fondu, déplace-le le long de la chanson ; double-clic pour en ajouter un, double-clic sur un point pour le retirer. La force ci-dessus est le haut de la courbe.",
