"{0} unknown: the pinned file list could not be read (offline?).": "{0} inconnu : la liste de fichiers épinglée n'a pas pu être lue (hors ligne ?).",
"No check has run here yet: Check again says what is here.": "Aucune vérification n'a encore tourné ici : Vérifier à nouveau dit ce qui est ici.",
"Checking what came…": "Vérification de ce qui est arrivé…",
"Not fetched:": "Non récupéré :",
"Not checked:": "Non vérifié :",
"Fetch {0}?": "Récupérer {0} ?",
"About {0}.": "Environ {0}.",
"Each file comes at the revision the release pins and is checked against its size; a download cut short goes on where it stopped.": "Chaque fichier arrive à la révision que la version épingle et est vérifié par sa taille ; un téléchargement interrompu reprend là où il s'est arrêté.",
"Fetch what is missing?": "Récupérer ce qui manque ?",
"Everything the install brings that is not here.": "Tout ce que l'installation apporte et qui n'est pas ici.",
"Fetch {0}: {1} ({2})?": "Récupérer {0} : {1} ({2}) ?",
"Restart the engine?": "Redémarrer le moteur ?",
"It then lists what came; the page reconnects by itself. Nothing may be rendering.": "Il liste ensuite ce qui est arrivé ; la page se reconnecte d'elle-même. Rien ne doit être en cours de rendu.",
"The engine restarts…": "Le moteur redémarre…",
"The studio does not run as a service here (Pinokio, or ./start.sh by hand): stop it and start it again there, and the engine lists what came.": "Le studio ne tourne pas ici comme service (Pinokio, ou ./start.sh à la main) : arrête-le et relance-le là-bas, et le moteur liste ce qui est arrivé.",
"Not restarted:": "Pas redémarré :",
"The extra decoders and the sliders, converted once ({0})": "Les décodeurs supplémentaires et les curseurs, convertis une fois ({0})",
"Checkpoints for the extra decoders and the sliders, made into GGUF here": "Points de contrôle des décodeurs supplémentaires et des curseurs, convertis en GGUF ici",
"Whisper large-v3 (CTranslate2, float16): lyrics check, karaoke timing, trim to the text": "Whisper large-v3 (CTranslate2, float16) : vérification des paroles, synchronisation karaoké, coupe au texte",
"LoRAs: the Kit's library and Ruach Studio's own": "LoRA : la bibliothèque du Kit et celle de Rouah Studio",
"M-A-P's YuE2 as GGUF (Serveurperso/YuE2-GGUF): Compute chooses between those here": "YuE2 de M-A-P en GGUF (Serveurperso/YuE2-GGUF) : Calcul choisit parmi ceux qui sont ici",
"M-A-P's YuE2 as GGUF": "YuE2 de M-A-P en GGUF",
"the whole model; on a card older than Ampere (an RTX 20xx, a Quadro RTX) it runs without its tensor cores, slower than Q8_0": "le modèle entier ; sur une carte plus ancienne qu'Ampere (une RTX 20xx, une Quadro RTX) il tourne sans ses cœurs tensoriels, plus lentement que Q8_0",
"The whole model; on a card older than Ampere (an RTX 20xx, a Quadro RTX) it runs without its tensor cores, slower than Q8_0": "Le modèle entier ; sur une carte plus ancienne qu'Ampere (une RTX 20xx, une Quadro RTX) il tourne sans ses cœurs tensoriels, plus lentement que Q8_0",
"Style listener": "Écouteur de style",
