"A folder that is there already; {0} goes into it as «{1}». On the same disk it is renamed at once; on another it is copied, checked file by file, then the link is switched, and the old copy stays, renamed, for you to remove after a look.": "Un dossier qui existe déjà ; {0} y entre sous le nom « {1} ». Sur le même disque il est renommé aussitôt ; sur un autre il est copié, vérifié fichier par fichier, puis le lien est changé, et l'ancienne copie reste, renommée, pour que tu la supprimes après un coup d'œil.",
