"TEST: none of the 110 official examples writes it, so YuE2 may sing it as words or pass it by. Listen before you keep it.": "TEST : aucun des 110 exemples officiels ne l'écrit, donc YuE2 peut le chanter comme des mots ou le passer. Écoute avant de le garder.",
