"{0} context": "contexte {0}",
"Not in OpenRouter's list: check the name": "Pas dans la liste d'OpenRouter : vérifie le nom",
"Any model of openrouter.ai/models, written provider/model; the field offers the whole list as you type, each with its price per million tokens in and out. The quick picks fill it in.": "N'importe quel modèle de openrouter.ai/models, écrit fournisseur/modèle ; le champ propose toute la liste pendant la frappe, chacun avec son prix par million de jetons en entrée et en sortie. Les choix rapides le remplissent.",
"Strong and the cheapest per word: the default · {0}": "Solide et le moins cher au mot : par défaut · {0}",
"none yet · load a model in the chat server": "aucun pour l'instant · charge un modèle dans le serveur de chat",
"Your draft is ready. Review and edit it, then apply what you like.": "Ton brouillon est prêt. Relis-le et modifie-le, puis applique ce qui te plaît.",
"Export all": "Tout exporter",
"Export all: every document of the Writer, with its versions, the takes made from it and its trash, in one file (a backup)": "Tout exporter : chaque document de l'Écrivain, avec ses versions, les prises faites à partir de lui et sa corbeille, dans un fichier (une sauvegarde)",
"Import a backup": "Importer une sauvegarde",
"Import a Writer backup: what is missing here comes in; the same is left alone; a document that differs from its namesake here comes in beside it as a copy. Nothing here is written over": "Importer une sauvegarde de l'Écrivain : ce qui manque ici arrive ; ce qui est identique est laissé tel quel ; un document qui diffère de son homonyme ici arrive à côté comme copie. Rien ici n'est écrasé",
"A Writer backup to import": "Une sauvegarde de l'Écrivain à importer",
"The documents column: drag to widen; ← → from the keyboard; Home or a double click for its own width": "La colonne des documents : glisse pour élargir ; ← → au clavier ; Début ou un double clic pour sa propre largeur",
"Writer backup: {0} documents and {1} in the trash, into {2}": "Sauvegarde de l'Écrivain : {0} documents et {1} dans la corbeille, dans {2}",
"not a Writer backup (a file this room exported)": "pas une sauvegarde de l'Écrivain (un fichier que cette salle a exporté)",
"Writer backup {0}: {1} new, {2} already here, {3} beside their namesakes as copies, {4} into the trash": "Sauvegarde de l'Écrivain {0} : {1} nouveaux, {2} déjà ici, {3} à côté de leurs homonymes comme copies, {4} dans la corbeille",
"Not imported: {0}": "Non importé : {0}",
"Wipe out the art's trash": "Vider la corbeille des illustrations",
