"Delete for good: {0} ({#1} MB).": "Supprimer définitivement : {0} ({#1} Mo).",
"This cannot be undone.\n\nThe covers of a frozen workspace's takes stay.": "Cela ne peut pas être annulé.\n\nLes pochettes des prises d'un espace gelé restent.",
