"Filter the takes shown: tick what to look for, and whether a take needs all of it (AND), any of it (OR) or none of it (NOR)": "Filtrer les prises affichées : coche ce qu'il faut chercher, et si une prise doit tout avoir (AND), n'importe lequel (OR) ou aucun (NOR)",
"Clear the choice": "Effacer le choix",
"The choice": "Le choix",
"To the trash: it gives them back until it is emptied": "À la corbeille : elle les rend jusqu'à ce qu'elle soit vidée",
"With what is made from them: also every file made from each take (remasters, stems, upscales, debuzzed files), named after the take.": "Avec ce qui est fait à partir d'elles : aussi chaque fichier fait à partir de chaque prise (remasters, stems, agrandissements, fichiers débuzzés), nommé d'après la prise.",
"Export ZIP: made on Forge, then saved by the browser where you tell it": "Exporter en ZIP : fait sur Forge, puis enregistré par le navigateur là où tu le dis",
