"not looked up yet": "pas encore recherché",
"What its trainer wrote into the file": "Ce que son entraîneur a écrit dans le fichier",
"The adapter could not be read: {0}": "L'adaptateur n'a pas pu être lu : {0}",
"Copied": "Copié",
"An adapter of the LoRA library": "Un adaptateur de la bibliothèque de LoRA",
