"Its score has one section only: nothing to crop by sections": "Sa partition n'a qu'une section : rien à rogner par sections",
"Its score has one section only: nothing to take out by sections": "Sa partition n'a qu'une section : rien à retirer par sections",
"Nothing taken out": "Rien de retiré",
"Nothing would be left of the take": "Il ne resterait rien de la prise",
"The new take has no score: its score could not be cut on those sections": "La nouvelle prise n'a pas de partition : sa partition n'a pas pu être coupée sur ces sections",
