"Speed": "Vitesse",
"{0} is at {#1} BPM: the new tempo in BPM, or a factor (×1.1, 90%)? From ×0.5 to ×2. A new take; this one stays.": "{0} est à {#1} BPM : le nouveau tempo en BPM, ou un facteur (×1.1, 90%) ? De ×0.5 à ×2. Une nouvelle prise ; celle-ci reste.",
"{0}: a factor (×1.1, 90%)? Its pitch stays. From ×0.5 to ×2. A new take; this one stays.": "{0} : un facteur (×1.1, 90%) ? Sa hauteur reste. De ×0.5 à ×2. Une nouvelle prise ; celle-ci reste.",
"Change the speed": "Changer la vitesse",
