"Changing the speed of {0} (×{1})…": "Changement de la vitesse de {0} (×{1})…",
"✦ Tighten": "✦ Resserrer",
"Tighten these lyrics: the Writer's model cuts filler and weak lines, keeps the meaning, the language, the rhymes and every section tag; you see both side by side before anything changes (Ctrl+Z in the box brings the old ones back)": "Resserrer ces paroles : le modèle de l'Écrivain coupe le remplissage et les lignes faibles, garde le sens, la langue, les rimes et chaque balise de section ; tu vois les deux côte à côte avant que rien ne change (Ctrl+Z dans le champ ramène les anciennes)",
"✦ Suggest": "✦ Suggérer",
"Style suggestions: the Writer's model reads the Style, the Title and the lyrics' first lines and offers short tags this song has not got yet; a click on one puts it in (before the BPM at its end)": "Suggestions de style : le modèle de l'Écrivain lit le Style, le Titre et les premières lignes des paroles et propose de courts tags que cette chanson n'a pas encore ; un clic sur l'un l'insère (avant le BPM à la fin)",
"Other suggestions": "Autres suggestions",
"Tighten these lyrics": "Resserrer ces paroles",
"Now {#0} words · tightened {#1} words": "Actuellement {#0} mots · resserré {#1} mots",
"Section tags the model left out: {0}": "Balises de section que le modèle a omises : {0}",
