"An adapter from Civitai into this family's folder: its link, and your own API key when it asks for one": "Un adaptateur de Civitai dans le dossier de cette famille : son lien, et ta propre clé d'API quand il en demande une",
"From Civitai…": "Depuis Civitai…",
"Or From Civitai… above: its link, and your own API key when it asks for one; the lab fetches it here.": "Ou Depuis Civitai… ci-dessus : son lien, et ta propre clé d'API quand il en demande une ; le labo le récupère ici.",
