"civitai.com → Account settings → API Keys": "civitai.com → Account settings → API Keys",
"Many adapters come without a key; some ask for one. The key goes from this page to the studio's lab and from there to civitai.com alone, never into a file.": "Beaucoup d'adaptateurs viennent sans clé ; certains en demandent une. La clé va de cette page au labo du studio et de là à civitai.com seulement, jamais dans un fichier.",
