"no such picture in the run: {0}": "pas d'image de ce nom dans l'exécution : {0}",
"Its strength over the steps: keyframes of a multiplier at a share of the steps, as ComfyUI's LoRA hooks. «0%:1, 50%:1, 60%:0» keeps it whole for half the steps and lets it go by 60 %; «0%:0, 30%:1» brings it in after the start. Between keyframes the multiplier runs straight; two at one share make a step.": "Sa force au fil des étapes : des images clés d'un multiplicateur à une part des étapes, comme les hooks de LoRA de ComfyUI. « 0%:1, 50%:1, 60%:0 » le garde entier la moitié des étapes et le laisse partir à 60 % ; « 0%:0, 30%:1 » le fait entrer après le début. Entre les images clés le multiplicateur varie en ligne droite ; deux à la même part font une marche.",
"Its strength over the steps": "Sa force au fil des étapes",
