"A track from anywhere (WAV, FLAC, MP3…) into the library as a take, marked imported; a way wired from here runs on each one imported next": "Une piste de n'importe où (WAV, FLAC, MP3…) dans la bibliothèque comme prise, marquée importée ; un chemin tracé d'ici tourne seul sur chaque import suivant",
