"The Debunker: a file or a set of stems balanced, compressed, toned and brought to a loudness": "Le Debunker : un fichier ou un jeu de stems équilibré, compressé, tonalisé et amené à une sonie",
"This machine's interfaces: the gateway's out and in, the monitor": "Les interfaces de cette machine : la sortie et l'entrée de la passerelle, le moniteur",
