"Out to the gear": "Sortie vers le matériel",
"In from the gear": "Entrée depuis le matériel",
"Rate": "Fréquence",
"Measure the input's floor": "Mesurer le plancher de l'entrée",
"Two seconds from the input: with nothing playing into it, the converter's own noise": "Deux secondes de l'entrée : sans rien qui y joue, le bruit propre du convertisseur",
"A plugin's analog step plays through the output chosen here and records from the input, at this rate.": "L'étape analogique d'un plugin joue par la sortie choisie ici et enregistre depuis l'entrée, à cette fréquence.",
"No sound card is seen here.": "Aucune carte son n'est vue ici.",
"Looking…": "Je regarde…",
"The lab did not answer: {0}": "Le labo n'a pas répondu : {0}",
"Choose the input first": "Choisis d'abord l'entrée",
"Listening to the input for two seconds…": "J'écoute l'entrée deux secondes…",
"The input's floor, RMS / peak dBFS: {0}": "Le plancher de l'entrée, RMS / crête dBFS : {0}",
"Not measured: {0}": "Pas mesuré : {0}",
"no sound card is seen here (/proc/asound has none)": "aucune carte son n'est vue ici (/proc/asound est vide)",
"aplay is not here: ALSA's software devices are not listed": "aplay n'est pas là : les périphériques logiciels d'ALSA ne sont pas listés",
"arecord is not here: ALSA's software devices are not listed": "arecord n'est pas là : les périphériques logiciels d'ALSA ne sont pas listés",
"PipeWire / Pulse do not run here (no pactl answer)": "PipeWire / Pulse ne tournent pas ici (pas de réponse de pactl)",
"JACK does not run here (no jack_lsp)": "JACK ne tourne pas ici (pas de jack_lsp)",
"the lab reaches the sound devices through sg audio: its service started before the audio group was given": "le labo atteint les périphériques son par sg audio : son service a démarré avant que le groupe audio soit donné",
"The interface the gateway plays a take out through, to the gear": "L'interface par laquelle la passerelle envoie la prise vers le matériel",
"The interface the gateway records the gear back from": "L'interface depuis laquelle la passerelle réenregistre le matériel",
"The rate both run at: the ones the chosen output and input both take": "La fréquence des deux : celles qu'acceptent la sortie et l'entrée choisies",
"A 1 kHz tone at −20 dBFS out through the output and back from the input: did it come back, its gain, the noise before it, its THD": "Un son de 1 kHz à −20 dBFS sort par la sortie et revient par l'entrée : s'il est revenu, son gain, le bruit avant, son THD",
"Loop test": "Test de boucle",
"Choose the output and the input first": "Choisis d'abord la sortie et l'entrée",
"A 1 kHz tone at −20 dBFS plays through {0} for two seconds. Turn the monitors down if they are on.": "Un son de 1 kHz à −20 dBFS jouera par {0} pendant deux secondes. Baisse les moniteurs s'ils sont allumés.",
"Play it": "Le jouer",
"The tone goes out and comes back…": "Le son sort et revient…",
"Nothing came back: the noise is {0} dBFS": "Rien n'est revenu : le bruit est de {0} dBFS",
"It came back: gain {0} dB, noise {1} dBFS, THD {2} %": "Il est revenu : gain {0} dB, bruit {1} dBFS, THD {2} %",
"The loop did not run: {0}": "La boucle n'a pas tourné : {0}",
"The setup as it is now (the steps' settings and where the nodes stand, never a take's sources) under a name": "La configuration telle qu'elle est (les réglages des étapes et la place des nœuds, jamais les sources d'une prise) sous un nom",
"Set every step as it was kept under this name": "Remettre chaque étape comme elle a été gardée sous ce nom",
"A name for this setup": "Un nom pour cette configuration",
"Set it": "Le remettre",
"Keep the setup as it is now under this name": "Garder la configuration actuelle sous ce nom",
"Delete the profile «{0}»?": "Supprimer le profil « {0} » ?",
"Profile «{0}» kept": "Profil « {0} » gardé",
"Profile «{0}» set: {1} settings changed": "Profil « {0} » remis : {1} réglages changés",
