"Clone": "Cloner",
"Delete the clone": "Supprimer le clone",
"A second node of this step with its own settings, beside it: its window holds them, and a run from there runs with them": "Un second nœud de cette étape avec ses propres réglages, à côté : sa fenêtre les garde, et un lancement depuis là tourne avec eux",
"its own settings": "ses propres réglages",
"{0} cloned: its window holds its own settings": "{0} cloné : sa fenêtre garde ses propres réglages",
"Delete the clone «{0}»? Its settings go with it.": "Supprimer le clone « {0} » ? Ses réglages partent avec lui.",
"Eight clones of one step are enough": "Huit clones d'une étape suffisent",
"Every Generate keeps this title's style, lyrics and score apart from the takes: its versions, a diff of two, one back into the form": "Chaque Generate garde le style, les paroles et la partition de ce titre à part des prises : ses versions, la différence de deux, une de retour dans le formulaire",
"Every Generate's words, kept under their title apart from the takes: a take deleted never takes them along": "Les mots de chaque Generate, gardés sous leur titre à part des prises : une prise supprimée ne les emporte jamais",
"Creator's versions": "Versions du Créateur",
"The Creator's version was not kept: {0}": "La version du Créateur n'a pas été gardée : {0}",
"The Creator's versions did not come: {0}": "Les versions du Créateur ne sont pas venues : {0}",
"too long to compare line by line": "trop long pour comparer ligne à ligne",
"the same": "pareil",
"unchanged lines: {0}": "lignes inchangées : {0}",
"a click picks a version; Ctrl or Shift and a click, a second: their difference": "un clic choisit une version ; Ctrl ou Maj et un clic, une seconde : leur différence",
"versions: {0}": "versions : {0}",
