"score": "partition",
"takes: {0}": "prises : {0}",
"Nothing kept under this title yet: every Generate keeps its words here.": "Rien n'est encore gardé sous ce titre : chaque Generate garde ici ses mots.",
"Trash ({0})": "Corbeille ({0})",
