"deleted from the library; its words are kept here": "supprimée de la bibliothèque ; ses mots sont gardés ici",
"Its title, style, lyrics and score into the Creator's form": "Son titre, son style, ses paroles et sa partition dans le formulaire du Créateur",
"★ Starred": "★ Étoilée",
