"Without a note": "Sans note",
// HERESY 1734: why the wave's section edits are greyed
"Sections and lyrics on the wave are off (the player's switch)": "Les sections et les paroles sur l'onde sont désactivées (l'interrupteur du lecteur)",
"These are the score's marks: Find the sections by ear first (in this menu)": "Ce sont les repères de la partition : d'abord « Trouver les sections à l'oreille » (dans ce menu)",
"No sections on the wave yet: Find the sections by ear (in this menu)": "Pas encore de sections sur l'onde : « Trouver les sections à l'oreille » (dans ce menu)",
"No section under the pointer": "Aucune section sous le pointeur",
"The rest of a part sung anew: the pointer over the part itself": "La suite d'une partie rechantée : le pointeur sur la partie elle-même",
"No words here, an instrumental part: the pointer over a sung section": "Pas de paroles ici, c'est une partie instrumentale : le pointeur sur une section chantée",
