// HERESY 1795: the DAW and the piano roll, a beta
"beta": "bêta",
"Beta: we make our songs here every day, and it is all still growing; what it keeps and how it looks may change in a later release.": "Bêta : nous y faisons nos chansons chaque jour, et tout cela grandit encore ; ce qu'il garde et son aspect peuvent changer dans une version ultérieure.",
// HERESY 1794: Ruach Studio's own fine-tune (RS-FW) in the Models card
"RS-FW merge": "Fusion RS-FW",
"YuE2-3B with Ruach Studio's own fine-tune folded in (YuE2-RS-FW, at seven points of its training: epoch x strength): 2.4x0.75 is the studio's default, the safest; from goldhub/YuE2-RS-Finetunes (CC BY-NC-SA 4.0). Compute chooses it beside m-a-p's backbones; the adapters themselves are not published": "YuE2-3B avec le fine-tune propre à Ruach Studio intégré (YuE2-RS-FW, en sept points de son entraînement : époque x force) : 2.4x0.75 est le modèle par défaut du studio, le plus sûr ; depuis goldhub/YuE2-RS-Finetunes (CC BY-NC-SA 4.0). Calcul la choisit à côté des modèles de base de m-a-p ; les adaptateurs eux-mêmes ne sont pas publiés",
