"One after another on Forge, the way in hand as it is set now; Stop lets the take in hand finish.": "L'une après l'autre sur Forge, le chemin en main tel qu'il est réglé maintenant ; Arrêter laisse finir la prise en cours.",
"The bucket:": "Le panier :",
