"ten takes at most": "dix prises au plus",
"ten takes at most; the way runs on them from the bucket in the Refiner's head": "dix prises au plus ; le chemin passe sur elles depuis le panier en tête de l'Affineur",
"muted: Ctrl+M unmutes": "en sourdine : Ctrl+M la réactive",
"{0} unmuted": "{0} : réactivé",
"{0} muted: it does not run, nor what follows it on the way": "{0} en sourdine : ne s'exécute pas, ni ce qui le suit sur le chemin",
"{0} is muted: Ctrl+M unmutes it": "{0} est en sourdine : Ctrl+M le réactive",
