"Ctrl+M: it does not run, nor what follows it on the way; Ctrl+B bypasses": "Ctrl+M : ne s'exécute pas, ni ce qui le suit sur le chemin ; Ctrl+B le contourne",
"Ctrl+M mutes, Ctrl+B bypasses the nodes selected or the one under the pointer; drag this legend where it suits": "Ctrl+M met en sourdine, Ctrl+B contourne les nœuds sélectionnés ou celui sous le pointeur ; glisse cette légende où elle convient",
"Unfold the legend: what each wire says": "Déplier la légende : ce que dit chaque fil",
"a dissolve": "un fondu enchaîné",
"every file made from it": "chaque fichier qui en est issu",
"The whole canvas in sight. Ctrl+wheel scales it (50–200 %), the wheel or a drag on its empty ground moves it": "Toute la toile en vue. Ctrl+molette la met à l'échelle (50–200 %) ; la molette ou un glisser sur son fond vide la déplace",
"Back to 100 %": "Revenir à 100 %",
"Titles on the clip": "Titres sur le clip",
"The song's title over the clip's first seconds and the credits over its last ones, both as written in «The idea and the look»": "Le titre de la chanson sur les premières secondes du clip et le générique sur les dernières, tels qu'écrits dans «L'idée et l'allure»",
"The title shown": "Le titre affiché",
"The title over the clip's first seconds; empty: the take's own": "Le titre sur les premières secondes du clip ; vide : celui de la prise",
"Credits": "Générique",
"The closing lines over the clip's last seconds, one a line: who sang, wrote, painted, shot": "Les lignes de fin sur les dernières secondes du clip, une par ligne : qui a chanté, écrit, peint, filmé",
"Cuts on the beat": "Coupes sur le temps",
"Cuts as sung": "Coupes comme chanté",
"Every cut between shots moved to the take's nearest beat (within 0.3 s, no shot under 1.5 s), the times as sung kept beside them; the button again, or Ctrl+Z on the timeline, takes them back": "Chaque coupe entre les plans sur le temps le plus proche de la prise (à 0,3 s au plus, aucun plan sous 1,5 s), les temps comme chanté gardés à côté ; le bouton de nouveau, ou Ctrl+Z sur la timeline, les remet",
"{0} of {1} cuts on the beat ({2} bpm), moved {3} ms on average": "{0} coupes sur {1} sur le temps ({2} bpm), déplacées de {3} ms en moyenne",
"{0} cuts back where they were sung": "{0} coupes de nouveau là où c'était chanté",
"hearing the take's beats…": "j'écoute les temps de la prise…",
"Editor (.zip)": "Montage (.zip)",
"The plan as an editor's project in one zip: an OpenTimelineIO timeline and an EDL for DaVinci Resolve or Kdenlive, the sung lines as subtitles, every shot's video or picture and the take's sound": "Le plan comme projet de montage en un zip : une timeline OpenTimelineIO et un EDL pour DaVinci Resolve ou Kdenlive, les lignes chantées en sous-titres, la vidéo ou l'image de chaque plan et le son de la prise",
"the editor's project: {0} shots, {1} MB": "le projet de montage : {0} plans, {1} Mo",
"the editor's project: gathering the shots…": "le projet de montage : je rassemble les plans…",
"{0} is no seed: back to −1, a new seed each run": "{0} n'est pas une graine : de nouveau −1, une graine nouvelle à chaque passe",
"A seed typed by hand is 1…999 999 999: {0} became 999 999 999": "Une graine tapée à la main va de 1 à 999 999 999 : {0} est devenue 999 999 999",
"the take's song cut into shots at its sung lines: the look and the scenes with the Writer, the pictures by the Artist, the moving shots by MiniMax H3, the clip": "la chanson de la prise découpée en plans sur ses lignes chantées : l'allure et les scènes avec l'Écrivain, les images du Peintre, les plans animés par MiniMax H3, le clip",
"🔍 Find a take…": "🔍 Trouver une prise…",
"Find a take by the words of its title or style, or among a workspace's takes (Ctrl+K in this room)": "Trouver une prise par les mots de son titre ou de son style, ou parmi les prises d'un espace (Ctrl+K dans cette pièce)",
"Find a take": "Trouver une prise",
"All takes": "Toutes les prises",
"This room over the whole screen; F11 in it does the same. Esc, F11 or this button back": "Cette pièce en plein écran ; F11 y fait de même. Retour : Échap, F11 ou ce bouton",
