"The shot after (Alt+→)": "Le plan d'après (Alt+→)",
"the strip: a click a shot, a double click plays from it": "la bande : un clic, un plan ; un double clic joue depuis lui",
"No animatic or clip yet: «Animatic» and «Clip» above make them.": "Pas encore d'animatique ni de clip : «Animatique» et «Clip» plus haut les font.",
