"🎬 Shoot all": "🎬 Tout tourner",
"The clip's shape": "Format du clip",
"The clip's shape: wide 16:9 (1920 × 1080) for a screen, tall 9:16 (1080 × 1920) for a phone's stories and shorts, square 1:1 (1080 × 1080); each shape is a clip of its own, the pictures cropped to it": "Le format du clip : large 16:9 (1920 × 1080) pour un écran, haut 9:16 (1080 × 1920) pour les stories et les shorts du téléphone, carré 1:1 (1080 × 1080) ; chaque format est un clip à part, les images recadrées pour lui",
"16:9 wide": "16:9 large",
"9:16 tall": "9:16 haut",
"1:1 square": "1:1 carré",
"Lyrics on the clip": "Paroles sur le clip",
"The sung lines burnt into the clip, each in its own time from the take's timing, at the foot of the picture": "Les lignes chantées incrustées dans le clip, chacune à son temps d'après le minutage de la prise, au bas de l'image",
"Between sections": "Entre les sections",
"How the clip passes from one section of the song to the next: a plain cut, through black, a flash of white, or a dissolve (the next section fading in over the last one's last half second); within a section the shots cut": "Comment le clip passe d'une section de la chanson à la suivante : une simple coupe, par le noir, un éclair blanc ou un fondu enchaîné (la section suivante apparaît sur la dernière demi-seconde de la précédente) ; dans une section les plans se coupent franc",
"a cut": "une coupe",
"through black": "par le noir",
"a flash": "un éclair",
"🎨 Draw the shots": "🎨 Peindre les plans",
"Draw the shots": "Peindre les plans",
"The Artist draws every shot that has no picture yet, two at a time on the free cards: the hero's shots from the hero's picture (Qwen-Image 2.1, then 2512 over it), the others by 2512 from their scene; each picture goes into its shot as it comes": "Le Peintre peint chaque plan qui n'a pas encore d'image, deux à la fois sur les cartes libres : les plans avec le héros d'après l'image du héros (Qwen-Image 2.1, puis 2512 par-dessus), les autres par 2512 d'après leur scène ; chaque image entre dans son plan dès qu'elle est prête",
"Stop drawing": "Arrêter la peinture",
"the Artist: {0} of {1}": "le Peintre : {0} sur {1}",
"the Artist drew {0} of {1}": "le Peintre a peint {0} sur {1}",
"the drawing stops after the shots on the cards": "la peinture s'arrête après les plans déjà sur les cartes",
"Pick the hero's picture first: «The look of the clip» → The hero": "D'abord l'image du héros : « L'allure du clip » → Le héros",
"The Artist draws the {0} shots that have no picture yet?\n\n{1} of them with the hero: Qwen-Image 2.1 from the hero's picture, then 2512 over it; the others by 2512 from their scene. Two at a time on the free cards, about a minute a shot; each picture goes into its shot as it comes.": "Le Peintre peint les {0} plans qui n'ont pas encore d'image ?\n\n{1} d'entre eux avec le héros : Qwen-Image 2.1 d'après l'image du héros, puis 2512 par-dessus ; les autres par 2512 d'après leur scène. Deux à la fois sur les cartes libres, environ une minute par plan ; chaque image entre dans son plan dès qu'elle est prête.",
"Every shot has its picture. Draw all {0} again? The pictures they have are put aside, not deleted.": "Chaque plan a son image. Les repeindre tous les {0} ? Les images actuelles sont mises de côté, pas effacées.",
"The hero": "Le héros",
"Pick the hero": "Choisir le héros",
"Another hero": "Un autre héros",
"Take the hero off": "Retirer le héros",
"No hero yet: every shot is drawn from its words": "Pas encore de héros : chaque plan est peint d'après ses mots",
"The hero: a picture of the Artist": "Le héros : une image du Peintre",
"Is the hero in this shot? Pressed: drawn from the hero's picture; not pressed: from the scene's words alone": "Le héros est-il dans ce plan ? Enfoncé : peint d'après l'image du héros ; relâché : d'après les seuls mots de la scène",
"the hero is set": "héros choisi",
"the hero is taken off": "héros retiré",
"The idea of the clip": "L'idée du clip",
"The clip's idea in a line or a few: what it is about, its mood, its story. The Writer writes the look and the scenes from it": "L'idée du clip en une ligne ou quelques-unes : de quoi il parle, son humeur, son histoire. L'Écrivain en écrit l'allure et les scènes",
