"⇮ Upscale all": "⇮ Tout upscaler",
"Upscale all": "Tout upscaler",
"SeedVR2 7B sharp to 1080p for every shot that has a video and no upscale yet, dealt among the free cards; the clip takes each one as it comes": "SeedVR2 7B sharp en 1080p pour chaque plan qui a une vidéo et pas encore d'upscale, réparti sur les cartes libres ; le clip prend chacun dès qu'il arrive",
"Upscale all {0} shots that have a video with SeedVR2 7B sharp to 1080p?\n\nOn the free cards, about four minutes for a shot of four seconds; the clip takes each one as it comes. A shot's 🎬 menu has 1440p and the quick 3B.": "Upscaler les {0} plans qui ont une vidéo avec SeedVR2 7B sharp en 1080p ?\n\nSur les cartes libres, environ quatre minutes pour un plan de quatre secondes ; le clip prend chacun dès qu'il arrive. Le menu 🎬 d'un plan propose le 1440p et le 3B rapide.",
"{0} shot(s) to SeedVR2 on {1} card(s)": "{0} plan(s) vers SeedVR2 sur {1} carte(s)",
"No shot with a video still to upscale": "Aucun plan avec vidéo n'attend d'upscale",
"Upscale: {0}": "Upscale : {0}",
"Upscale failed: {0}": "Échec de l'upscale : {0}",
"Upscaled by SeedVR2 to {0}p": "Upscalé par SeedVR2 en {0}p",
"Videographer · SeedVR2 upscaler": "Vidéaste · upscaler SeedVR2",
"7B sharp": "7B sharp",
"the quick one: 18.6 GB of a card at 1080p, 10 GB of RAM": "la rapide : 18,6 Go de carte en 1080p, 10 Go de RAM",
"the studio's own: 20 GB of a card at 1080p (16 of its blocks in RAM), 21 GB of RAM; 1440p fits too": "celui du studio : 20 Go de carte en 1080p (16 de ses blocs en RAM), 21 Go de RAM ; le 1440p tient aussi",
"3B, 7B sharp and 7B": "3B, 7B sharp et 7B",
"SeedVR2 (ByteDance, Apache-2.0) as numz packs it: the Videographer's upscaler, a shot's video to 1080p or 1440p in one step, the details made anew. Measured on an RTX 3090, 107 frames of 768p: 3B to 1080p in 284 s, 7B sharp in 367 s, 7B sharp to 1440p in 592 s": "SeedVR2 (ByteDance, Apache-2.0) tel que numz l'empaquette : l'upscaler du Vidéaste, la vidéo d'un plan en 1080p ou 1440p en une étape, les détails refaits à neuf. Mesuré sur une RTX 3090, 107 images en 768p : 3B en 1080p en 284 s, 7B sharp en 367 s, 7B sharp en 1440p en 592 s",
"Blind listening": "Écoute à l'aveugle",
