"with its parent": "avec son espace parent",
"blind": "à l'aveugle",
"Blind listening: what made this take (its model, adapters, seeds and decoder, its time and its folder) stays hidden until its workspace's blindness is lifted (⋯ beside its name)": "Écoute à l'aveugle : comment cette prise a été faite (son modèle, ses adaptateurs, ses seeds et son décodeur, son heure et son dossier) reste caché tant que l'aveugle de son espace n'est pas levé (⋯ à côté de son nom)",
