"Style and lyrics": "Style et paroles",
"Its style and lyrics in a sheet beside the window": "Son style et ses paroles sur une feuille à côté de la fenêtre",
"Close the sheet (Esc)": "Fermer la feuille (Échap)",
"Drag its corner to make it wider and taller; a double click here puts its size back": "Tire son coin pour l'élargir et l'agrandir ; un double clic ici lui rend sa taille",
"No style": "Pas de style",
"No lyrics": "Pas de paroles",
"What the player in the rooms' footer and the window comparing takes stream: FLAC is the take itself, lossless (about 30 MB for a song of four minutes); Opus at 128 kbit/s is about 4 MB, made on the studio's machine the first time a take plays, for a slow line (a phone, a VPN). Everywhere else the studio hears and measures the lossless FLAC, and downloads stay WAV and FLAC.": "Ce que le lecteur du pied des salles et la fenêtre de comparaison des prises envoient à la page : le FLAC est la prise elle-même, sans perte (environ 30 Mo pour une chanson de quatre minutes) ; l'Opus à 128 kbit/s fait environ 4 Mo, créé sur la machine du studio la première fois qu'une prise joue, pour une ligne lente (un téléphone, un VPN). Partout ailleurs le studio écoute et mesure le FLAC sans perte, et les téléchargements restent en WAV et FLAC.",
"Videographer · MiniMax H3": "Vidéaste · MiniMax H3",
"All int8 tiers": "Tous les niveaux int8",
"the studio's own: a card of 24 GB and 64 GB of RAM": "celui du studio : une carte de 24 Go et 64 Go de RAM",
"both modes whole and pruned, FastH3, ControlNet Union and the effects too": "les deux modes entiers et élagués, plus FastH3, ControlNet Union et les effets",
"unquantized, for cards of 80 GB; on 24 GB only streamed from RAM, slowly": "non quantifié, pour des cartes de 80 Go ; sur 24 Go seulement en flux depuis la RAM, lentement",
"MiniMax H3 (MiniMax) as Comfy-Org packs it: the Videographer's moving pictures, a shot at a time on a card of 24 GB, the shot's picture its first frame. Its licence (the MiniMax H3 Community License) does not allow running it on your own machines in the United States, the European Union, the United Kingdom or South Korea, and commercial use beyond the threshold it names needs MiniMax's own licence. Where you run it and what you make with it is yours to answer for: read the licence before you fetch it": "MiniMax H3 (MiniMax) tel que Comfy-Org l'empaquette : les images animées du Vidéaste, un plan à la fois sur une carte de 24 Go, l'image du plan pour première image. Sa licence (MiniMax H3 Community License) ne permet pas de l'exécuter sur tes propres machines aux États-Unis, dans l'Union européenne, au Royaume-Uni ou en Corée du Sud, et l'usage commercial au-delà du seuil qu'elle fixe exige une licence propre de MiniMax. Où tu l'exécutes et ce que tu en fais relève de ta responsabilité : lis la licence avant de le télécharger",
"Shoot this shot with MiniMax H3: a draft (8 steps) or the final (28 steps); its picture, when it has one, is its first frame": "Tourner ce plan avec MiniMax H3 : un brouillon (8 pas) ou le définitif (28 pas) ; son image, s'il en a une, est la première image",
"Every shot with MiniMax H3 as a draft (8 steps), shot by shot on the free cards; a shot's picture, when it has one, is its first frame": "Tous les plans avec MiniMax H3 en brouillons (8 pas), plan par plan sur les cartes libres ; l'image d'un plan, s'il en a une, est sa première image",
"Shoot all {0} shots with MiniMax H3 as drafts?\n\nOn the free cards, a few minutes a shot; the clip takes each shot's video as it comes.": "Tourner les {0} plans avec MiniMax H3 en brouillons ?\n\nSur les cartes libres, quelques minutes par plan ; le clip prend la vidéo de chaque plan dès qu'elle arrive.",
