"Open in the Videographer": "Ouvrir dans le Vidéaste",
"Find a take: words of its title or style": "Trouver une prise : mots du titre ou du style",
"no take found": "aucune prise trouvée",
"Writer: the chat server at {0} does not answer. The studio's own Writer is here:": "Écrivain : le serveur de chat sur {0} ne répond pas. L'Écrivain du studio est là :",
"Who is in the clip: each person as they look, the same in every shot": "Qui figure dans le clip : chaque personne telle qu'elle apparaît, la même dans chaque plan",
"Where the clip happens": "Où se passe le clip",
"The clip's colours and light": "Les couleurs et la lumière du clip",
"How the clip moves through the song: its line from the first shot to the last": "Comment le clip traverse la chanson : sa ligne du premier plan au dernier",
"No note yet: a click writes one": "Pas de note : un clic l'écrit",
"Videographer": "Vidéaste",
"The Videographer (beta): a take cut into shots at its sung lines, the look and every shot's scene written with the Writer; the moving pictures come with MiniMax H3": "Vidéaste (bêta) : une prise découpée en plans sur ses vers chantés, l'allure du clip et la scène de chaque plan écrites avec l'Écrivain ; les images animées viennent avec MiniMax H3",
"A take's song cut into shots at its sung lines, the look of the clip and each shot's scene, written with the Writer and yours to change. The moving pictures come with MiniMax H3.": "La chanson d'une prise découpée en plans sur ses vers chantés, l'allure du clip et la scène de chaque plan, écrites avec l'Écrivain et à toi de les changer. Les images animées viennent avec MiniMax H3.",
"The moving pictures will come from MiniMax H3, which you download yourself from MiniMax's own repository: the studio does not ship it. Its licence (the MiniMax Community License) does not allow running it on your own machines in the United States, the European Union, the United Kingdom or South Korea, and commercial use beyond the threshold it names needs MiniMax's own licence. Where you run it and what you make with it is yours to answer for: read the licence before you download it.": "Les images animées viendront de MiniMax H3, que tu télécharges toi-même depuis le dépôt de MiniMax : le studio ne le fournit pas. Sa licence (MiniMax Community License) n'autorise pas son exécution sur tes propres machines aux États-Unis, dans l'Union européenne, au Royaume-Uni ni en Corée du Sud, et un usage commercial au-delà du seuil qu'elle fixe demande une licence propre de MiniMax. Où tu l'exécutes et ce que tu en fais relève de ta responsabilité : lis la licence avant de le télécharger.",
