"A minute with the studio counts when a page played or was in your hands in it; however many pages, a minute is one. The takes from their meta.json; the machine once a minute, kept by the hour; the folders without what their links lead to elsewhere.": "Une minute avec le studio compte quand une page a joué ou était entre tes mains ; quel que soit le nombre de pages, la minute est une. Les prises d'après leur meta.json ; la machine une fois par minute, gardée par heure ; les dossiers sans ce vers quoi leurs liens mènent ailleurs.",
"One click: back to the start of this take (at its start already: the take above). Two clicks within a second: the take above in the list": "Un clic : au début de cette prise (déjà au début : la prise du dessus). Deux clics en une seconde : la prise du dessus dans la liste",
"Dislike: the take leaves the lists while «Show disliked takes in the lists» is off (Engine → Defaults); «Only the disliked» still finds it": "Je n'aime pas : la prise quitte les listes tant que « Montrer les prises 👎 dans les listes » est désactivé (Moteur → Par défaut) ; « Seulement les pas aimées » la trouve toujours",
"The player's buttons and texts at rest": "Boutons et textes du lecteur au repos",
"How solid the player's buttons, marks and times stand while the pointer is not on them; under the pointer they are always whole. The studio's own: 60 %": "L'opacité des boutons, marques et temps du lecteur quand le pointeur n'est pas dessus ; sous le pointeur ils sont toujours entiers. Celle du studio : 60 %",
"Hints": "Aides",
"Tips over buttons and fields, on the pointer": "Info-bulles sur les boutons et les champs",
