"Delete {0} saves of {1} for good?": "Supprimer définitivement {0} sauvegardes de {1} ?",
"{0} of them are in loras/, in the Creator's LoRAs. Take them out too (the space comes back), or keep them usable?": "Parmi eux, dans loras/ (les LoRA du Créateur) : {0}. Les retirer aussi (l'espace revient) ou les garder utilisables ?",
"{0} saves deleted, {1} back on the disk": "Sauvegardes supprimées : {0} ; {1} libérés sur le disque",
