"every take": "toutes les prises",
"Only the takes with this mark play; the playlist keeps every take": "Seules les prises portant cette marque sont lues ; la playlist les garde toutes",
"Up next": "À suivre",
"in {0} s": "dans {0} s",
"Play it now": "La lire maintenant",
"Which quant the studio's writer runs: quality keeps the AutoRound 4 bits as they are (about 7.5 GB of VRAM), compact keeps those and lowers the rest (about 6.5 GB). Only those here can be chosen": "Quelle quantification l'écrivain du studio exécute : qualité garde les 4 bits d'AutoRound tels quels (environ 7,5 Go de VRAM), compact les garde et abaisse le reste (environ 6,5 Go). Seuls ceux présents se choisissent",
"Quality: the AutoRound 4 bits as they are (a 12 GB card)": "Qualité : les 4 bits d'AutoRound tels quels (une carte de 12 Go)",
"Compact: for an 8 GB card": "Compact : pour une carte de 8 Go",
"Not here yet: Engine → Models and LoRAs → Studio writer fetches it (6.7 GB; compact 5.5 GB).": "Pas encore ici : Moteur → Modèles et LoRA → Écrivain du studio le télécharge (6,7 Go ; le compact 5,5 Go).",
"Its weights are here; llama.cpp's llama-server is not built yet: launcher/extras.sh builds it.": "Ses poids sont ici ; le llama-server de llama.cpp n'est pas encore compilé : launcher/extras.sh le compile.",
"Qwopus3.5-9B-v3 (Jackrong's, on Qwen3.5-9B, Apache-2.0), quantized with AutoRound, through llama.cpp on this machine: nothing leaves it. It starts at the first question and leaves the card after 10 minutes without one.": "Qwopus3.5-9B-v3 (de Jackrong, sur Qwen3.5-9B, Apache-2.0), quantifié avec AutoRound, via llama.cpp sur cette machine : rien n'en sort. Il démarre à la première question et quitte la carte après 10 minutes sans question.",
"not here": "pas ici",
"llama-server not built": "llama-server non compilé",
"asleep": "en veille",
"on the processor": "sur le processeur",
