"on GPU {0}": "sur le GPU {0}",
"Studio writer": "Écrivain du studio",
"Quality": "Qualité",
"Compact": "Compact",
"about 7.5 GB of VRAM with its 12K context: a 12 GB card": "environ 7,5 Go de VRAM avec son contexte de 12K : une carte de 12 Go",
"about 6.5 GB of VRAM with its 12K context: an 8 GB card": "environ 6,5 Go de VRAM avec son contexte de 12K : une carte de 8 Go",
"Qwopus3.5-9B-v3 (Jackrong's fine-tune of Qwen3.5-9B, Apache-2.0), quantized with AutoRound and moved into GGUF bit for bit, from goldhub/Ruach_Studio_Models_v2: the Writer's own language model on this machine, through llama.cpp (vendor/llama.cpp, built by launcher/extras.sh); Engine → Writer chooses between those here": "Qwopus3.5-9B-v3 (l'affinage de Qwen3.5-9B par Jackrong, Apache-2.0), quantifié avec AutoRound et passé en GGUF bit pour bit, depuis goldhub/Ruach_Studio_Models_v2 : le modèle de langue propre à l'Écrivain sur cette machine, via llama.cpp (vendor/llama.cpp, compilé par launcher/extras.sh) ; Moteur → Écrivain choisit parmi ceux présents",
"← → keys": "Touches ← →",
"Shift + ← →": "Maj + ← →",
"Start playing": "Commencer à jouer",
"when its first minute is in and the rest will come in time": "quand sa première minute est là et que le reste arrivera à temps",
"when the whole take is in": "quand toute la prise est là",
"On a slow line (a studio far away), a take can start before all of it has come: once its first minute is in and the rest will come before the playing reaches it; where it changes to the whole, it does so at a quiet moment. At home the whole comes within seconds, and it waits for it either way.": "Sur une ligne lente (un studio au loin), une prise peut commencer avant d'être arrivée en entier : dès que sa première minute est là et que le reste arrivera avant que la lecture l'atteigne ; là où elle passe à l'entière, elle le fait à un moment calme. À la maison l'entière arrive en quelques secondes, et elle l'attend de toute façon.",
"A click on a take plays it": "Un clic sur une prise la joue",
"New takes play when they are done": "Les nouvelles prises jouent dès qu'elles sont prêtes",
"A double-click on a card plays or stops it": "Un double-clic sur une carte la joue ou l'arrête",
"Show disliked takes in the lists": "Montrer les prises 👎 dans les listes",
