"Recordings: the layer's first field recording in the bank (for the fireplace, Dartington); Recordings II: its second (Lithuania). Synthesis: made here; for rain II is a downpour, for the canary I is a roller, II a timbrado, III a wild song. A fireplace, a forest and tropical birds are recordings only": "Enregistrements : le premier enregistrement de terrain de la couche dans la banque (pour la cheminée, Dartington) ; Enregistrements II : le deuxième (Lituanie). Synthèse : fait ici ; pour la pluie, II est une averse ; pour le canari, I est un roller, II un timbrado, III un chant sauvage. La cheminée, la forêt et les oiseaux tropicaux sont des enregistrements seulement",
"Synthesis": "Synthèse",
"Recordings: the layer's first field recording in the bank, chosen by ear (for the fireplace, Dartington); Recordings II: its second. Synthesis only where it held up by ear, light rain and thunder; the other layers are recordings only": "Enregistrements : le premier enregistrement de terrain de la couche dans la banque, choisi à l'oreille (pour la cheminée, Dartington) ; Enregistrements II : le deuxième. Synthèse seulement là où elle a tenu à l'écoute : pluie légère et tonnerre ; les autres couches sont des enregistrements seulement",
